-- Root supplies exact approved artifacts in temp table continuity_registration_metadata_v6(review jsonb,options_review jsonb,git_commit text).
DO $register$
DECLARE ctl jsonb;m record;review_id bigint;handler_review_id bigint;functions jsonb;h text;ev bigint;
BEGIN
 ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 SELECT * INTO STRICT m FROM continuity_registration_metadata_v6;
 IF m.review->>'approved' IS DISTINCT FROM 'true' OR m.review->>'producer' IS DISTINCT FROM 'blocked_dispatch' OR m.review->>'reviewer' IS DISTINCT FROM 'continuity_review' OR m.review#>>'{actual_runtime_evidence,event_id}' IS DISTINCT FROM '18030' OR m.review#>>'{artifact_sha256,continuity_v6/runtime/continuation_queue_v6.sql}' IS DISTINCT FROM 'c7b4084d4dcc898e8d3bc3df3f9df200081327d676c0f34b42614f68b9948a53' OR m.git_commit!~'^[0-9a-f]{40}$' THEN RAISE EXCEPTION 'CONTINUATION_EXACT_INDEPENDENT_REVIEW_REQUIRED';END IF;
 h:=encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx02_clear_page_admission_v6(text,bigint,bigint,jsonb)'::regprocedure),'UTF8')),'hex');
 IF h<>'b93de6769c09ff602183ed8d1a5ce073781c5b47a88d2939886186ad78faa7d2' OR m.options_review->>'installed_function_sha256' IS DISTINCT FROM h OR m.options_review->>'producer' IS DISTINCT FROM 'options_recovery' OR m.options_review->>'reviewer' IS DISTINCT FROM 'continuity_review' OR m.options_review->>'decision' IS DISTINCT FROM 'APPROVE_EXACT_HANDLER_INTEGRATION' OR m.options_review#>>'{runtime_evidence,result}' IS DISTINCT FROM 'PASS_OPTIONS_ALLOWANCE_REQUEUE_ROLLBACK_V6' THEN RAISE EXCEPTION 'CONTINUATION_EXACT_OPTIONS_HANDLER_REVIEW_REQUIRED';END IF;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CONTINUATION_INDEPENDENT_REVIEW_V6',m.review||ctl||jsonb_build_object('git_commit',m.git_commit,'review_sha256',encode(sha256(convert_to(m.review::text,'UTF8')),'hex'))) RETURNING event_id INTO review_id;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CONTINUATION_OPTIONS_HANDLER_REVIEW_V6',m.options_review||ctl||jsonb_build_object('approved',true,'handler_function_sha256',h,'git_commit',m.git_commit)) RETURNING event_id INTO handler_review_id;
 INSERT INTO population_top3000_202608_202609_v1.continuation_handler_v6(kind,function_oid,function_sha256,review_event_id,bounds,enabled) VALUES('CTX02_PAGE_ADMISSION','population_top3000_202608_202609_v1.ctx02_clear_page_admission_v6(text,bigint,bigint,jsonb)'::regprocedure,h,handler_review_id,'{"maximum_new_pages":50,"absolute_page_ceiling":997,"maximum_handler_calls_per_dispatch_pass":1,"minimum_pass_seconds":60}'::jsonb,true);
 SELECT jsonb_object_agg(p.oid::regprocedure::text,encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')) INTO functions FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='population_top3000_202608_202609_v1' AND (p.proname LIKE 'continuation_%_v6' OR p.proname IN('pipeline_tick_v1','ctx02_clear_page_admission_v6'));
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('ENGINEERING_INTEGRATED_V5',ctl||jsonb_build_object('assignment_id','continuity-v6-runtime','authority_receipt_event_id',17776,'git_commit',m.git_commit,'independent_review_event_id',review_id,'options_handler_review_event_id',handler_review_id,'actual_test_event_id',18030,'installed_functions',functions,'recovery_manifest',population_top3000_202608_202609_v1.population_recovery_manifest_v1(),'useful_output_observed',false,'no_family_acceptance',true)) RETURNING event_id INTO ev;
 PERFORM population_top3000_202608_202609_v1.pipeline_wake_v1(ctl->>'owner_id',(ctl->>'owner_fence')::bigint,'Reviewed durable clearing dispatcher integration; useful commits remain required');
END;$register$;
COMMIT;
